package tw.rex.link;
import android.app.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;
public final class Skin {
 public static final String[] IDS={"ocean","forest","space","garden"};
 public static final String[] NAMES={"海洋鯊魚樂園","奶油森林學園","星空夢想基地","彩繪貓咪花園"};
 public static final String[] DESCRIPTIONS={"湛藍海水・小鯊魚與海龜","奶油暖色・小熊兔兔與狐狸","夢幻紫色・太空貓咪與月亮兔","原創貓耳女孩・滑板與花朵"};
 public interface Choice {void selected(String id);}
 static final android.util.LruCache<String,Bitmap> CACHE=new android.util.LruCache<String,Bitmap>(32*1024*1024){protected int sizeOf(String k,Bitmap b){return b.getByteCount();}};
 public static boolean valid(String id){return Arrays.asList(IDS).contains(id);}
 public static int index(String id){for(int i=0;i<IDS.length;i++)if(IDS[i].equals(id))return i;return 0;}
 public static String id(Context c){String id=c.getSharedPreferences("appearance",0).getString("skin","ocean");return valid(id)?id:"ocean";}
 public static String name(Context c){return NAMES[index(id(c))];}
 public static void set(Context c,String id){if(!valid(id))throw new IllegalArgumentException("未知皮膚");c.getSharedPreferences("appearance",0).edit().putString("skin",id).commit();}
 public static int dp(Context c,float n){return (int)(n*c.getResources().getDisplayMetrics().density+.5f);}
 public static int ink(Context c){return new int[]{0xff123f60,0xff5b3a22,0xff402267,0xff654238}[index(id(c))];}
 public static int accent(Context c){return new int[]{0xff079bb5,0xff658a37,0xff8d4dd1,0xffbc6384}[index(id(c))];}
 public static int soft(Context c){return new int[]{0xffd9f7fb,0xffedf1d7,0xffecdeff,0xffffeadb}[index(id(c))];}
 public static int panelColor(Context c){return new int[]{0xf7f4fdff,0xf9fff8e8,0xf9f8efff,0xf9fff6ed}[index(id(c))];}
 static int[] colors(Context c,int type){int skin=index(id(c));int[][][] cs={{{0xfffff1ba,0xffffdf86},{0xffffe1de,0xffffc6bd},{0xffe4e3ff,0xffc9c6fb}},{{0xffffefd4,0xfff5d6a4},{0xffedf3d5,0xffcdda9f},{0xffffe1ce,0xfff6bfa2}},{{0xfff4ddff,0xffd8b7ff},{0xffe1e4ff,0xffb9b2fa},{0xffffe0ed,0xfff8b9d9}},{{0xffffe4c9,0xffffce9e},{0xffedf3da,0xffcbdcae},{0xfff4e0fa,0xffdfbdea}}};return cs[skin][((type%3)+3)%3];}
 public static GradientDrawable panel(Context c){GradientDrawable d=new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,new int[]{panelColor(c),panelColor(c)});d.setCornerRadius(dp(c,23));d.setStroke(dp(c,1.5f),0xcfffffff);return d;}
 static GradientDrawable buttonBg(Context c,int type,boolean focused){GradientDrawable d=new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,colors(c,type));d.setCornerRadius(dp(c,21));d.setStroke(dp(c,focused?4:1.5f),focused?0xffffc83d:0xe8ffffff);return d;}
 public static void styleButton(Button b,int type){Context c=b.getContext();StateListDrawable states=new StateListDrawable();states.addState(new int[]{-android.R.attr.state_enabled},panel(c));states.addState(new int[]{android.R.attr.state_focused},buttonBg(c,type,true));states.addState(new int[]{android.R.attr.state_pressed},buttonBg(c,type,true));states.addState(new int[]{},buttonBg(c,type,false));b.setBackground(states);b.setTextColor(ink(c));b.setAllCaps(false);b.setTypeface(null,Typeface.BOLD);b.setTag("skin.button."+type);b.setElevation(dp(c,4));b.setPadding(dp(c,14),dp(c,8),dp(c,14),dp(c,8));b.setMinHeight(dp(c,52));b.setOnFocusChangeListener((v,focus)->{b.animate().scaleX(focus?1.018f:1).scaleY(focus?1.018f:1).setDuration(140).start();b.setTextColor(ink(c));});}
 public static Button button(Context c,String label,int type){Button b=new Button(c);b.setText(label);b.setTextSize(18);styleButton(b,type);return b;}
 public static void card(View view){view.setTag("skin.panel");view.setBackground(panel(view.getContext()));view.setElevation(dp(view.getContext(),3));}
 public static void text(TextView t){t.setTextColor(ink(t.getContext()));t.setTag("skin.text");}
 public static void trimMemory(){CACHE.evictAll();}
 public static boolean television(Context c){return(c.getResources().getConfiguration().uiMode&android.content.res.Configuration.UI_MODE_TYPE_MASK)==android.content.res.Configuration.UI_MODE_TYPE_TELEVISION;}
 public static Bitmap bitmap(Context c,String id,boolean tv){String path="skins/"+id+(tv?"_tv.webp":"_phone.webp");Bitmap b=CACHE.get(path);if(b!=null)return b;try(InputStream in=c.getAssets().open(path)){BitmapFactory.Options o=new BitmapFactory.Options();o.inPreferredConfig=Bitmap.Config.ARGB_8888;if(tv&&!television(c))o.inSampleSize=2;b=BitmapFactory.decodeStream(in,null,o);if(b!=null)CACHE.put(path,b);return b;}catch(Exception e){return null;}}
 public static Drawable background(Context c,boolean tv){return new Wallpaper(c,tv,null,false);}
 public static View mascot(Context c){View v=new View(c);v.setBackground(new Wallpaper(c,true,null,true));return v;}
 public static Bitmap icons(Context c){String path="skins/icons.webp";Bitmap b=CACHE.get(path);if(b!=null)return b;try(InputStream in=c.getAssets().open(path)){BitmapFactory.Options o=new BitmapFactory.Options();if(!television(c))o.inSampleSize=2;b=BitmapFactory.decodeStream(in,null,o);if(b!=null)CACHE.put(path,b);return b;}catch(Exception e){return null;}}
 public static View icon(Context c,int column){return new Icon(c,column);}
 public static View feature(Context c,String title,String caption,int column){LinearLayout card=new LinearLayout(c);card.setOrientation(1);card.setGravity(Gravity.CENTER);card.setPadding(dp(c,12),dp(c,10),dp(c,12),dp(c,12));card.setTag("skin.feature."+column);card.setBackground(buttonBg(c,column,false));card.setElevation(dp(c,7));card.setFocusable(true);card.setClickable(true);card.addView(icon(c,column),new LinearLayout.LayoutParams(-1,0,1));TextView name=new TextView(c);name.setText(title);name.setTextSize(23);name.setTypeface(null,Typeface.BOLD);name.setGravity(Gravity.CENTER);text(name);card.addView(name);TextView detail=new TextView(c);detail.setText(caption);detail.setTextSize(13);detail.setGravity(Gravity.CENTER);text(detail);card.addView(detail);card.setOnFocusChangeListener((v,f)->{card.setBackground(buttonBg(c,column,f));card.animate().scaleX(f?1.025f:1).scaleY(f?1.025f:1).setDuration(140).start();card.setElevation(dp(c,f?13:7));});return card;}
 public static class Icon extends View {final int column;final Paint paint=new Paint(3);Icon(Context c,int column){super(c);this.column=column;setTag("skin.icon");setImportantForAccessibility(IMPORTANT_FOR_ACCESSIBILITY_NO);}protected void onDraw(Canvas canvas){boolean garden="garden".equals(id(getContext()));Bitmap b=garden?bitmap(getContext(),"garden",true):icons(getContext());if(b==null)return;int row=index(id(getContext()));int sw=b.getWidth()/3,sh=b.getHeight()/3;Rect source;if(garden){float[][] regions={{.015f,.32f,.225f,.84f},{.18f,.45f,.405f,.97f},{.70f,.45f,.925f,.94f}};float[] region=regions[Math.max(0,Math.min(2,column))];source=new Rect((int)(b.getWidth()*region[0]),(int)(b.getHeight()*region[1]),(int)(b.getWidth()*region[2]),(int)(b.getHeight()*region[3]));sw=source.width();sh=source.height();}else{source=new Rect(column*sw,row*sh,(column+1)*sw,(row+1)*sh);}float scale=Math.min(getWidth()/(float)sw,getHeight()/(float)sh);RectF target=new RectF((getWidth()-sw*scale)/2f,(getHeight()-sh*scale)/2f,(getWidth()+sw*scale)/2f,(getHeight()+sh*scale)/2f);canvas.drawBitmap(b,source,target,paint);}}
 public static void restyle(View root){Object tag=root.getTag();if(tag instanceof String){String role=(String)tag;if(role.startsWith("skin.button.")&&root instanceof Button){try{styleButton((Button)root,Integer.parseInt(role.substring(12)));if(((Button)root).getText().toString().startsWith("換皮膚 ·"))((Button)root).setText("換皮膚 · "+name(root.getContext()));}catch(Exception e){styleButton((Button)root,0);}}else if(role.startsWith("skin.feature.")){try{root.setBackground(buttonBg(root.getContext(),Integer.parseInt(role.substring(13)),root.isFocused()));}catch(Exception e){}}else if(role.equals("skin.panel"))root.setBackground(panel(root.getContext()));else if(role.equals("skin.text")&&root instanceof TextView)((TextView)root).setTextColor(ink(root.getContext()));}
 if(root instanceof EditText){((EditText)root).setTextColor(ink(root.getContext()));((EditText)root).setHintTextColor(0xff72778a);}else if(root instanceof CheckBox){((CheckBox)root).setTextColor(ink(root.getContext()));((CheckBox)root).setButtonTintList(android.content.res.ColorStateList.valueOf(accent(root.getContext())));}if(root instanceof ViewGroup){ViewGroup group=(ViewGroup)root;for(int i=0;i<group.getChildCount();i++)restyle(group.getChildAt(i));}root.invalidate();}
 public static void picker(Context a,String current,Choice choice){LinearLayout list=new LinearLayout(a);list.setOrientation(1);list.setPadding(dp(a,14),dp(a,10),dp(a,14),dp(a,10));final AlertDialog[] holder=new AlertDialog[1];for(int i=0;i<IDS.length;i++){final int selected=i;LinearLayout row=new LinearLayout(a);row.setOrientation(0);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(a,10),dp(a,8),dp(a,10),dp(a,8));row.setBackground(buttonBg(a,i,current.equals(IDS[i])));row.setFocusable(true);row.setClickable(true);row.setOnFocusChangeListener((v,f)->row.setBackground(buttonBg(a,selected,f||current.equals(IDS[selected]))));View preview=new View(a);preview.setBackground(new Wallpaper(a,true,IDS[i],false));row.addView(preview,new LinearLayout.LayoutParams(dp(a,132),dp(a,74)));LinearLayout words=new LinearLayout(a);words.setOrientation(1);words.setPadding(dp(a,14),0,0,0);TextView name=new TextView(a);name.setText(NAMES[i]+(current.equals(IDS[i])?"  ✓":""));name.setTextSize(19);name.setTypeface(null,Typeface.BOLD);name.setTextColor(ink(a));words.addView(name);TextView subtitle=new TextView(a);subtitle.setText(DESCRIPTIONS[i]);subtitle.setTextSize(13);subtitle.setTextColor(ink(a));words.addView(subtitle);row.addView(words,new LinearLayout.LayoutParams(0,-2,1));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,0,0,dp(a,10));list.addView(row,p);row.setOnClickListener(v->{choice.selected(IDS[selected]);holder[0].dismiss();});}
 ScrollView scroll=new ScrollView(a);scroll.addView(list);holder[0]=new AlertDialog.Builder(a).setTitle("選擇喜歡的皮膚").setView(scroll).setNegativeButton("取消",null).create();if(!(a instanceof Activity))holder[0].getWindow().setType(android.os.Build.VERSION.SDK_INT>=26?WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY:WindowManager.LayoutParams.TYPE_PHONE);holder[0].show();}
 public static class Wallpaper extends Drawable {
 final Context context;final boolean tv,mascot;final String fixed;final Paint paint=new Paint(3);final Matrix matrix=new Matrix();
 Wallpaper(Context c,boolean tv,String fixed,boolean mascot){context=c;this.tv=tv;this.fixed=fixed;this.mascot=mascot;}
 public void draw(Canvas canvas){Rect bounds=getBounds();Bitmap b=bitmap(context,fixed==null?id(context):fixed,tv);paint.setColor(soft(context));canvas.drawRect(bounds,paint);if(b==null)return;canvas.save();canvas.clipRect(bounds);if(mascot){Rect source=new Rect(0,(int)(b.getHeight()*.55f),(int)(b.getWidth()*.34f),b.getHeight());float scale=Math.min(bounds.width()/(float)source.width(),bounds.height()/(float)source.height());RectF target=new RectF(bounds.centerX()-source.width()*scale/2,bounds.centerY()-source.height()*scale/2,bounds.centerX()+source.width()*scale/2,bounds.centerY()+source.height()*scale/2);canvas.drawBitmap(b,source,target,paint);}else{float scale=Math.max(bounds.width()/(float)b.getWidth(),bounds.height()/(float)b.getHeight());matrix.reset();matrix.setScale(scale,scale);matrix.postTranslate(bounds.left+(bounds.width()-b.getWidth()*scale)/2f,bounds.top+(bounds.height()-b.getHeight()*scale)/2f);canvas.drawBitmap(b,matrix,paint);}canvas.restore();}
 public void setAlpha(int alpha){paint.setAlpha(alpha);invalidateSelf();}public void setColorFilter(ColorFilter filter){paint.setColorFilter(filter);invalidateSelf();}public int getOpacity(){return PixelFormat.OPAQUE;}
 }
}
